$chapters = @"

,  {"id":"SAT-10-18-01","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 18: Social Science Passage Analysis","yearEC":"2024 E.C.","questionText":"Social sciences study:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"human behavior and societies"},{"id":"b","text":"plants only"},{"id":"c","text":"chemicals only"},{"id":"d","text":"numbers only"}],"correctOptionId":"a","explanation":"Social sciences examine human behavior, societies, and social relationships.","difficulty":"Easy"},
  {"id":"SAT-10-18-02","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 18: Social Science Passage Analysis","yearEC":"2024 E.C.","questionText":"A survey is a method to:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"collect data from a group"},{"id":"b","text":"experiment on individuals"},{"id":"c","text":"observe nature"},{"id":"d","text":"analyze chemicals"}],"correctOptionId":"a","explanation":"Surveys gather information from people through questions.","difficulty":"Easy"},
  {"id":"SAT-10-18-03","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 18: Social Science Passage Analysis","yearEC":"2024 E.C.","questionText":"A demographic study examines:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"population characteristics"},{"id":"b","text":"chemical reactions"},{"id":"c","text":"plant growth"},{"id":"d","text":"rock formations"}],"correctOptionId":"a","explanation":"Demographics studies population characteristics like age, gender, and income.","difficulty":"Easy"},
  {"id":"SAT-10-18-04","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 18: Social Science Passage Analysis","yearEC":"2024 E.C.","questionText":"Correlation means:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"variables are related"},{"id":"b","text":"one causes the other"},{"id":"c","text":"variables are equal"},{"id":"d","text":"no relationship"}],"correctOptionId":"a","explanation":"Correlation indicates a relationship between variables.","difficulty":"Easy"},
  {"id":"SAT-10-18-05","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 18: Social Science Passage Analysis","yearEC":"2024 E.C.","questionText":"A theory in social science:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"explains observed phenomena"},{"id":"b","text":"is always proven"},{"id":"c","text":"is a guess"},{"id":"d","text":"cannot be tested"}],"correctOptionId":"a","explanation":"Theories provide explanations for observed social phenomena.","difficulty":"Easy"},
  {"id":"SAT-10-18-06","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 18: Social Science Passage Analysis","yearEC":"2024 E.C.","questionText":"Ethical research:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"protects participants"},{"id":"b","text":"ignores consent"},{"id":"c","text":"hides results"},{"id":"d","text":"fakes data"}],"correctOptionId":"a","explanation":"Ethical research ensures participant safety, informed consent, and honest reporting.","difficulty":"Easy"},
  {"id":"SAT-10-18-07","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 18: Social Science Passage Analysis","yearEC":"2024 E.C.","questionText":"Peer-reviewed articles:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"have been evaluated by experts"},{"id":"b","text":"are always correct"},{"id":"c","text":"need no evaluation"},{"id":"d","text":"are blog posts"}],"correctOptionId":"a","explanation":"Peer-reviewed articles are evaluated by field experts before publication.","difficulty":"Easy"},
  {"id":"SAT-10-18-08","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 18: Social Science Passage Analysis","yearEC":"2024 E.C.","questionText":"Bias in research:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"skews results toward expected outcome"},{"id":"b","text":"improves accuracy"},{"id":"c","text":"strengthens findings"},{"id":"d","text":"ensures validity"}],"correctOptionId":"a","explanation":"Bias can distort research findings and reduce credibility.","difficulty":"Easy"},
  {"id":"SAT-10-18-09","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 18: Social Science Passage Analysis","yearEC":"2024 E.C.","questionText":"A qualitative study:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"explores experiences and meanings"},{"id":"b","text":"uses only numbers"},{"id":"c","text":"excludes context"},{"id":"d","text":"ignores participants"}],"correctOptionId":"a","explanation":"Qualitative research explores experiences, meanings, and social processes.","difficulty":"Easy"},
  {"id":"SAT-10-18-10","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 18: Social Science Passage Analysis","yearEC":"2024 E.C.","questionText":"Quantitative study:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"uses numerical data"},{"id":"b","text":"uses only stories"},{"id":"c","text":"avoids statistics"},{"id":"d","text":"ignores numbers"}],"correctOptionId":"a","explanation":"Quantitative research collects and analyzes numerical data.","difficulty":"Easy"},
  {"id":"SAT-10-18-11","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 18: Social Science Passage Analysis","yearEC":"2024 E.C.","questionText":"Sampling bias:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"sample not representative"},{"id":"b","text":"sample too random"},{"id":"c","text":"sample perfect"},{"id":"d","text":"sample large enough"}],"correctOptionId":"a","explanation":"Sampling bias occurs when certain groups are over- or under-represented.","difficulty":"Medium"},
  {"id":"SAT-10-18-12","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 18: Social Science Passage Analysis","yearEC":"2024 E.C.","questionText":"Operationalization:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"defines how variables are measured"},{"id":"b","text":"hides methodology"},{"id":"c","text":"ignores definitions"},{"id":"d","text":"skips measurement"}],"correctOptionId":"a","explanation":"Operationalization defines exactly how abstract concepts are measured.","difficulty":"Medium"},
  {"id":"SAT-10-18-13","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 18: Social Science Passage Analysis","yearEC":"2024 E.C.","questionText":"Longitudinal study:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"follows subjects over time"},{"id":"b","text":"studies one moment"},{"id":"c","text":"uses one group only"},{"id":"d","text":"ignores changes"}],"correctOptionId":"a","explanation":"Longitudinal studies collect data from the same subjects repeatedly over time.","difficulty":"Medium"},
  {"id":"SAT-10-18-14","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 18: Social Science Passage Analysis","yearEC":"2024 E.C.","questionText":"Cross-sectional study:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"studies different groups at one time"},{"id":"b","text":"follows one group over time"},{"id":"c","text":"ignores comparisons"},{"id":"d","text":"uses only interviews"}],"correctOptionId":"a","explanation":"Cross-sectional studies compare different groups at a single point in time.","difficulty":"Medium"},
  {"id":"SAT-10-18-15","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 18: Social Science Passage Analysis","yearEC":"2024 E.C.","questionText":"Control group:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"receives no treatment"},{"id":"b","text":"receives treatment"},{"id":"c","text":"is eliminated"},{"id":"d","text":"is random"}],"correctOptionId":"a","explanation":"Control groups provide a baseline for comparison with treatment groups.","difficulty":"Medium"},
  {"id":"SAT-10-18-16","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 18: Social Science Passage Analysis","yearEC":"2024 E.C.","questionText":"External validity:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"results generalize to other settings"},{"id":"b","text":"results apply only to study"},{"id":"c","text":"methodology is weak"},{"id":"d","text":"data is fake"}],"correctOptionId":"a","explanation":"External validity means findings can be generalized beyond the study.","difficulty":"Medium"},
  {"id":"SAT-10-18-17","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 18: Social Science Passage Analysis","yearEC":"2024 E.C.","questionText":"Internal validity:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"study measured what it intended"},{"id":"b","text":"results generalize"},{"id":"c","text":"sample was large"},{"id":"d","text":"data was complete"}],"correctOptionId":"a","explanation":"Internal validity means the study accurately measured what it claimed to measure.","difficulty":"Medium"},
  {"id":"SAT-10-18-18","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 18: Social Science Passage Analysis","yearEC":"2024 E.C.","questionText":"Pseudoscience:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"claims scientific basis without evidence"},{"id":"b","text":"is well-researched"},{"id":"c","text":"uses scientific method"},{"id":"d","text":"is peer-reviewed"}],"correctOptionId":"a","explanation":"Pseudoscience presents unproven claims as scientific facts.","difficulty":"Medium"},
  {"id":"SAT-10-18-19","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 18: Social Science Passage Analysis","yearEC":"2024 E.C.","questionText":"Anecdotal evidence:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"based on personal stories"},{"id":"b","text":"statistically valid"},{"id":"c","text":"based on large samples"},{"id":"d","text":"always reliable"}],"correctOptionId":"a","explanation":"Anecdotal evidence relies on individual experiences rather than systematic data.","difficulty":"Medium"},
  {"id":"SAT-10-18-20","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 18: Social Science Passage Analysis","yearEC":"2024 E.C.","questionText":"Hawthorne effect:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"subjects change behavior when observed"},{"id":"b","text":"subjects ignore observers"},{"id":"c","text":"researchers change results"},{"id":"d","text":"data corrects itself"}],"correctOptionId":"a","explanation":"The Hawthorne effect occurs when subjects modify behavior because they know they are being studied.","difficulty":"Medium"},
  {"id":"SAT-10-18-21","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 18: Social Science Passage Analysis","yearEC":"2024 E.C.","questionText":"Ethnocentrism:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"judging other cultures by own standards"},{"id":"b","text":"appreciating all cultures equally"},{"id":"c","text":"studying multiple cultures"},{"id":"d","text":"avoiding cultural comparison"}],"correctOptionId":"a","explanation":"Ethnocentrism uses one's own culture as the standard for evaluating others.","difficulty":"Hard"},
  {"id":"SAT-10-18-22","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 18: Social Science Passage Analysis","yearEC":"2024 E.C.","questionText":"Selection bias in surveys:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"certain groups more likely to respond"},{"id":"b","text":"questions are confusing"},{"id":"c","text":"sample is random"},{"id":"d","text":"responses are honest"}],"correctOptionId":"a","explanation":"Selection bias occurs when respondents differ systematically from the population.","difficulty":"Hard"},
  {"id":"SAT-10-18-23","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 18: Social Science Passage Analysis","yearEC":"2024 E.C.","questionText":"Confirmation bias:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"seeking information that confirms beliefs"},{"id":"b","text":"considering all evidence equally"},{"id":"c","text":"changing beliefs based on evidence"},{"id":"d","text":"avoiding information"}],"correctOptionId":"a","explanation":"Confirmation bias favors information that supports existing beliefs.","difficulty":"Hard"},
  {"id":"SAT-10-18-24","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 18: Social Science Passage Analysis","yearEC":"2024 E.C.","questionText":"Response bias:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"participants give inaccurate answers"},{"id":"b","text":"participants are honest"},{"id":"c","text":"questions are clear"},{"id":"d","text":"sample is representative"}],"correctOptionId":"a","explanation":"Response bias occurs when participants provide inaccurate or dishonest answers.","difficulty":"Hard"},
  {"id":"SAT-10-18-25","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 18: Social Science Passage Analysis","yearEC":"2024 E.C.","questionText":"Cohort study:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"follows group sharing characteristic over time"},{"id":"b","text":"studies random individuals"},{"id":"c","text":"uses one measurement"},{"id":"d","text":"ignores time factor"}],"correctOptionId":"a","explanation":"Cohort studies follow a group sharing a characteristic over time.","difficulty":"Hard"},
  {"id":"SAT-10-18-26","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 18: Social Science Passage Analysis","yearEC":"2024 E.C.","questionText":"Case-control study:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"compares cases with and without condition"},{"id":"b","text":"follows one group only"},{"id":"c","text":"uses no comparison"},{"id":"d","text":"ignores past exposure"}],"correctOptionId":"a","explanation":"Case-control studies compare those with a condition to those without it.","difficulty":"Hard"},
  {"id":"SAT-10-18-27","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 18: Social Science Passage Analysis","yearEC":"2024 E.C.","questionText":"Confound:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"variable that distorts true relationship"},{"id":"b","text":"clear relationship"},{"id":"c","text":"controlled variable"},{"id":"d","text":"dependent variable"}],"correctOptionId":"a","explanation":"A confound is an uncontrolled variable that may explain observed effects.","difficulty":"Hard"},
  {"id":"SAT-10-18-28","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 18: Social Science Passage Analysis","yearEC":"2024 E.C.","questionText":"Replication crisis:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"many studies cannot be reproduced"},{"id":"b","text":"studies always replicate"},{"id":"c","text":"replication is easy"},{"id":"d","text":"replication is unnecessary"}],"correctOptionId":"a","explanation":"The replication crisis involves inability to reproduce results of many scientific studies.","difficulty":"Hard"},
  {"id":"SAT-10-18-29","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 18: Social Science Passage Analysis","yearEC":"2024 E.C.","questionText":"Publication bias:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"positive results more likely published"},{"id":"b","text":"all results equally published"},{"id":"c","text":"negative results preferred"},{"id":"d","text":"no bias exists"}],"correctOptionId":"a","explanation":"Publication bias favors studies with significant positive results.","difficulty":"Hard"},
  {"id":"SAT-10-18-30","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 18: Social Science Passage Analysis","yearEC":"2024 E.C.","questionText":"Social desirability bias:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"respondents answer to appear favorable"},{"id":"b","text":"respondents are honest"},{"id":"c","text":"questions are neutral"},{"id":"d","text":"data is accurate"}],"correctOptionId":"a","explanation":"Social desirability bias occurs when participants give answers they think are socially acceptable.","difficulty":"Hard"},
  {"id":"SAT-10-19-01","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 19: Historical Passage Analysis","yearEC":"2024 E.C.","questionText":"Primary sources:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"are created during the time period"},{"id":"b","text":"are written later"},{"id":"c","text":"are always accurate"},{"id":"d","text":"are secondary"}],"correctOptionId":"a","explanation":"Primary sources are original materials from the historical period being studied.","difficulty":"Easy"},
  {"id":"SAT-10-19-02","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 19: Historical Passage Analysis","yearEC":"2024 E.C.","questionText":"Secondary sources:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"analyze or interpret primary sources"},{"id":"b","text":"are created during the event"},{"id":"c","text":"are always biased"},{"id":"d","text":"are original documents"}],"correctOptionId":"a","explanation":"Secondary sources interpret, analyze, or summarize primary sources.","difficulty":"Easy"},
  {"id":"SAT-10-19-03","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 19: Historical Passage Analysis","yearEC":"2024 E.C.","questionText":"Historical context refers to:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"conditions surrounding an event"},{"id":"b","text":"only dates"},{"id":"c","text":"only people"},{"id":"d","text":"only places"}],"correctOptionId":"a","explanation":"Historical context includes social, political, economic, and cultural conditions.","difficulty":"Easy"},
  {"id":"SAT-10-19-04","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 19: Historical Passage Analysis","yearEC":"2024 E.C.","questionText":"Cause and effect in history:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"events are connected"},{"id":"b","text":"events are isolated"},{"id":"c","text":"nothing causes anything"},{"id":"d","text":"only one cause exists"}],"correctOptionId":"a","explanation":"Historical events are often interconnected through causal relationships.","difficulty":"Easy"},
  {"id":"SAT-10-19-05","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 19: Historical Passage Analysis","yearEC":"2024 E.C.","questionText":"Periodization:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"dividing history into time periods"},{"id":"b","text":"ignoring time"},{"id":"c","text":"using only dates"},{"id":"d","text":"avoiding chronology"}],"correctOptionId":"a","explanation":"Periodization organizes history into meaningful time segments.","difficulty":"Easy"},
  {"id":"SAT-10-19-06","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 19: Historical Passage Analysis","yearEC":"2024 E.C.","questionText":"A primary source example:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"diary from the period"},{"id":"b","text":"textbook about the period"},{"id":"c","text":"documentary film"},{"id":"d","text":"history book"}],"correctOptionId":"a","explanation":"A diary written during the event is a primary source.","difficulty":"Easy"},
  {"id":"SAT-10-19-07","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 19: Historical Passage Analysis","yearEC":"2024 E.C.","questionText":"Historical significance:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"why an event matters"},{"id":"b","text":"when it happened"},{"id":"c","text":"where it happened"},{"id":"d","text":"who was involved"}],"correctOptionId":"a","explanation":"Historical significance examines why an event or figure is important.","difficulty":"Easy"},
  {"id":"SAT-10-19-08","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 19: Historical Passage Analysis","yearEC":"2024 E.C.","questionText":"Perspective in history:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"viewpoint of the observer"},{"id":"b","text":"objective truth only"},{"id":"c","text":"single interpretation"},{"id":"d","text":"final answer"}],"correctOptionId":"a","explanation":"Different observers may have different perspectives on the same events.","difficulty":"Easy"},
  {"id":"SAT-10-19-09","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 19: Historical Passage Analysis","yearEC":"2024 E.C.","questionText":"A timeline shows:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"events in chronological order"},{"id":"b","text":"only important events"},{"id":"c","text":"only dates"},{"id":"d","text":"interpretations"}],"correctOptionId":"a","explanation":"Timelines arrange events in the order they occurred.","difficulty":"Easy"},
  {"id":"SAT-10-19-10","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 19: Historical Passage Analysis","yearEC":"2024 E.C.","questionText":"Cause vs. context:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"cause explains why, context provides background"},{"id":"b","text":"they are the same"},{"id":"c","text":"context is more important"},{"id":"d","text":"cause is irrelevant"}],"correctOptionId":"a","explanation":"Causes explain why events happened; context provides the surrounding conditions.","difficulty":"Easy"},
  {"id":"SAT-10-19-11","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 19: Historical Passage Analysis","yearEC":"2024 E.C.","questionText":"Bias in historical sources:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"reflects author's perspective"},{"id":"b","text":"is always present equally"},{"id":"c","text":"can be eliminated completely"},{"id":"d","text":"makes source useless"}],"correctOptionId":"a","explanation":"Historical sources reflect their authors' perspectives and should be analyzed critically.","difficulty":"Medium"},
  {"id":"SAT-10-19-12","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 19: Historical Passage Analysis","yearEC":"2024 E.C.","questionText":"Historiography:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"study of how history is written"},{"id":"b","text":"writing history novels"},{"id":"c","text":"memorizing dates"},{"id":"d","text":"ignoring sources"}],"correctOptionId":"a","explanation":"Historiography examines how historians have interpreted and written about the past.","difficulty":"Medium"},
  {"id":"SAT-10-19-13","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 19: Historical Passage Analysis","yearEC":"2024 E.C.","questionText":"Continuity:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"things that remain the same"},{"id":"b","text":"things that change"},{"id":"c","text":"new developments"},{"id":"d","text":"conflicts"}],"correctOptionId":"a","explanation":"Continuity refers to elements that persist through change over time.","difficulty":"Medium"},
  {"id":"SAT-10-19-14","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 19: Historical Passage Analysis","yearEC":"2024 E.C.","questionText":"Change over time:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"how things develop historically"},{"id":"b","text":"things staying the same"},{"id":"c","text":"ignoring development"},{"id":"d","text":"avoiding chronology"}],"correctOptionId":"a","explanation":"Examining change over time is fundamental to historical analysis.","difficulty":"Medium"},
  {"id":"SAT-10-19-15","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 19: Historical Passage Analysis","yearEC":"2024 E.C.","questionText":"Multiple perspectives:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"provide fuller understanding"},{"id":"b","text":"confuse the picture"},{"id":"c","text":"are unnecessary"},{"id":"d","text":"are always wrong"}],"correctOptionId":"a","explanation":"Multiple perspectives provide a more complete understanding of historical events.","difficulty":"Medium"},
  {"id":"SAT-10-19-16","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 19: Historical Passage Analysis","yearEC":"2024 E.C.","questionText":"Corroboration:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"confirming with multiple sources"},{"id":"b","text":"using one source only"},{"id":"c","text":"ignoring sources"},{"id":"d","text":"hiding evidence"}],"correctOptionId":"a","explanation":"Corroboration means verifying information across multiple independent sources.","difficulty":"Medium"},
  {"id":"SAT-10-19-17","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 19: Historical Passage Analysis","yearEC":"2024 E.C.","questionText":"Contextualization:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"placing events in broader context"},{"id":"b","text":"isolating events"},{"id":"c","text":"ignoring background"},{"id":"d","text":"using only dates"}],"correctOptionId":"a","explanation":"Contextualization places historical events within their broader circumstances.","difficulty":"Medium"},
  {"id":"SAT-10-19-18","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 19: Historical Passage Analysis","yearEC":"2024 E.C.","questionText":"Historical empathy:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"understanding past perspectives"},{"id":"b","text":"agreeing with past actions"},{"id":"c","text":"imposing modern views"},{"id":"d","text":"ignoring differences"}],"correctOptionId":"a","explanation":"Historical empathy means understanding people in their historical context.","difficulty":"Medium"},
  {"id":"SAT-10-19-19","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 19: Historical Passage Analysis","yearEC":"2024 E.C.","questionText":"Sourcing:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"examining origin of documents"},{"id":"b","text":"using any source"},{"id":"c","text":"ignoring authorship"},{"id":"d","text":"accepting all sources"}],"correctOptionId":"a","explanation":"Sourcing involves examining who created the document and why.","difficulty":"Medium"},
  {"id":"SAT-10-19-20","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 19: Historical Passage Analysis","yearEC":"2024 E.C.","questionText":"Causation:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"relationship between events"},{"id":"b","text":"random occurrences"},{"id":"c","text":"unrelated events"},{"id":"d","text":"single events"}],"correctOptionId":"a","explanation":"Causation examines how events relate to and influence each other.","difficulty":"Medium"},
  {"id":"SAT-10-19-21","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 19: Historical Passage Analysis","yearEC":"2024 E.C.","questionText":"Counterfactual thinking:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"what might have happened differently"},{"id":"b","text":"what definitely happened"},{"id":"c","text":"ignoring alternatives"},{"id":"d","text":"using only facts"}],"correctOptionId":"a","explanation":"Counterfactual thinking explores alternative outcomes by changing key factors.","difficulty":"Hard"},
  {"id":"SAT-10-19-22","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 19: Historical Passage Analysis","yearEC":"2024 E.C.","questionText":"Presentism:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"judging past by present standards"},{"id":"b","text":"understanding past in its own context"},{"id":"c","text":"ignoring present"},{"id":"d","text":"using past standards"}],"correctOptionId":"a","explanation":"Presentism is the tendency to interpret past events in terms of modern values.","difficulty":"Hard"},
  {"id":"SAT-10-19-23","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 19: Historical Passage Analysis","yearEC":"2024 E.C.","questionText":"Historical significance is determined by:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"impact and lasting effects"},{"id":"b","text":"only when it happened"},{"id":"c","text":"only where it happened"},{"id":"d","text":"only who was involved"}],"correctOptionId":"a","explanation":"Significance is determined by the impact and enduring effects of events.","difficulty":"Hard"},
  {"id":"SAT-10-19-24","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 19: Historical Passage Analysis","yearEC":"2024 E.C.","questionText":"Turning points:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"events that change direction"},{"id":"b","text":"minor events"},{"id":"c","text":"unimportant events"},{"id":"d","text":"ordinary events"}],"correctOptionId":"a","explanation":"Turning points are events that significantly alter the course of history.","difficulty":"Hard"},
  {"id":"SAT-10-19-25","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 19: Historical Passage Analysis","yearEC":"2024 E.C.","questionText":"Periodization debates:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"how to divide history into periods"},{"id":"b","text":"what dates to use"},{"id":"c","text":"who created periods"},{"id":"d","text":"where periods occurred"}],"correctOptionId":"a","explanation":"Historians debate how to organize history into meaningful periods.","difficulty":"Hard"},
  {"id":"SAT-10-19-26","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 19: Historical Passage Analysis","yearEC":"2024 E.C.","questionText":"Social history:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"focuses on ordinary people"},{"id":"b","text":"focuses only on leaders"},{"id":"c","text":"ignores society"},{"id":"d","text":"focuses only on politics"}],"correctOptionId":"a","explanation":"Social history examines the experiences of ordinary people and social structures.","difficulty":"Hard"},
  {"id":"SAT-10-19-27","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 19: Historical Passage Analysis","yearEC":"2024 E.C.","questionText":"Historical thinking skills:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"analysis, evaluation, synthesis"},{"id":"b","text":"memorization only"},{"id":"c","text":"guessing"},{"id":"d","text":"ignoring evidence"}],"correctOptionId":"a","explanation":"Historical thinking involves analyzing, evaluating, and synthesizing information.","difficulty":"Hard"},
